//! Offline Lean5 syntax validation for generated proof terms.
//!
//! This module provides a lightweight syntax checker that validates the
//! structure of Lean5 source files generated by [`crate::lean_export`]
//! without requiring the `lean` binary. It checks:
//!
//! - Balanced delimiters (braces, brackets, parentheses, angle brackets)
//! - Valid Lean5 identifier names
//! - Correct `theorem`/`def`/`axiom`/`abbrev`/`structure` declaration structure
//! - No dangling clause references (every `clause_N` in a theorem is defined)
//! - Presence of the `proof_valid` theorem

use std::collections::HashSet;

// ---------------------------------------------------------------------------
// Error type
// ---------------------------------------------------------------------------

/// A syntax error found during offline validation.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
#[error("line {line}: {message}")]
pub struct SyntaxError {
    /// 1-based line number where the error was detected.
    pub line: usize,
    /// Human-readable description of the error.
    pub message: String,
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/// Validate the syntax of a Lean5 source string produced by `export_lean5`.
///
/// Returns `Ok(())` if no errors are found, or `Err(errors)` with a list of
/// all detected issues. The checker is intentionally conservative: it
/// validates structural properties of the generated output, not the full
/// Lean5 grammar.
#[must_use = "validation result should be checked"]
pub fn validate_lean_syntax(lean_source: &str) -> Result<(), Vec<SyntaxError>> {
    let mut errors = Vec::new();

    check_balanced_delimiters(lean_source, &mut errors);
    check_declarations(lean_source, &mut errors);
    check_clause_references(lean_source, &mut errors);
    check_proof_valid_present(lean_source, &mut errors);
    check_by_decide_pairs(lean_source, &mut errors);

    if errors.is_empty() {
        Ok(())
    } else {
        errors.sort_by_key(|e| e.line);
        Err(errors)
    }
}

/// Check whether a string is a valid Lean5 identifier.
///
/// Valid identifiers start with a letter or underscore and contain only
/// letters, digits, underscores, and single quotes (primes). Qualified
/// names with dots (e.g., `Clause.isEmpty`) are also accepted.
#[must_use]
pub fn is_valid_lean_ident(s: &str) -> bool {
    if s.is_empty() {
        return false;
    }
    // Split on dots for qualified identifiers like Clause.isEmpty
    for part in s.split('.') {
        if part.is_empty() {
            return false;
        }
        let mut chars = part.chars();
        let Some(first) = chars.next() else {
            return false;
        };
        if !first.is_ascii_alphabetic() && first != '_' {
            return false;
        }
        if !chars.all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '\'') {
            return false;
        }
    }
    true
}

// ---------------------------------------------------------------------------
// Delimiter balance
// ---------------------------------------------------------------------------

fn check_balanced_delimiters(source: &str, errors: &mut Vec<SyntaxError>) {
    let mut stack: Vec<(char, usize)> = Vec::new();

    for (line_idx, line) in source.lines().enumerate() {
        let line_num = line_idx + 1;

        // Skip comment lines
        if line.trim_start().starts_with("--") {
            continue;
        }

        for ch in line.chars() {
            match ch {
                '(' | '[' | '{' | '\u{27e8}' => {
                    stack.push((ch, line_num));
                }
                ')' | ']' | '}' | '\u{27e9}' => {
                    let expected_open = match ch {
                        ')' => '(',
                        ']' => '[',
                        '}' => '{',
                        '\u{27e9}' => '\u{27e8}',
                        _ => unreachable!(),
                    };
                    match stack.pop() {
                        Some((open, _)) if open == expected_open => {}
                        Some((open, open_line)) => {
                            errors.push(SyntaxError {
                                line: line_num,
                                message: format!(
                                    "mismatched delimiter: found '{}' but expected match for '{}' from line {}",
                                    ch, open, open_line
                                ),
                            });
                        }
                        None => {
                            errors.push(SyntaxError {
                                line: line_num,
                                message: format!("unmatched closing delimiter '{ch}'"),
                            });
                        }
                    }
                }
                _ => {}
            }
        }
    }

    for (open, line_num) in stack {
        errors.push(SyntaxError {
            line: line_num,
            message: format!("unclosed delimiter '{open}'"),
        });
    }
}

// ---------------------------------------------------------------------------
// Declaration structure
// ---------------------------------------------------------------------------

fn check_declarations(source: &str, errors: &mut Vec<SyntaxError>) {
    for (line_idx, line) in source.lines().enumerate() {
        let line_num = line_idx + 1;
        let trimmed = line.trim();

        // Skip comments and empty lines
        if trimmed.is_empty() || trimmed.starts_with("--") {
            continue;
        }

        if trimmed.starts_with("def ") {
            check_def_declaration(trimmed, line_num, errors);
        }

        if trimmed.starts_with("theorem ") {
            check_theorem_declaration(trimmed, line_num, errors);
        }

        if trimmed.starts_with("axiom ") {
            check_axiom_declaration(trimmed, line_num, errors);
        }

        if trimmed.starts_with("abbrev ") {
            check_abbrev_declaration(trimmed, line_num, errors);
        }
    }
}

fn check_def_declaration(line: &str, line_num: usize, errors: &mut Vec<SyntaxError>) {
    let after_def = &line["def ".len()..];
    let ident = after_def.split_whitespace().next().unwrap_or("");
    if !is_valid_lean_ident(ident) {
        errors.push(SyntaxError {
            line: line_num,
            message: format!("invalid identifier in def declaration: '{ident}'"),
        });
    }
    if !line.contains(":=") {
        errors.push(SyntaxError {
            line: line_num,
            message: "def declaration missing ':='".to_string(),
        });
    }
}

fn check_theorem_declaration(line: &str, line_num: usize, errors: &mut Vec<SyntaxError>) {
    let after_theorem = &line["theorem ".len()..];
    let ident = after_theorem.split_whitespace().next().unwrap_or("");
    if !is_valid_lean_ident(ident) {
        errors.push(SyntaxError {
            line: line_num,
            message: format!("invalid identifier in theorem declaration: '{ident}'"),
        });
    }
    if !line.contains(':') {
        errors.push(SyntaxError {
            line: line_num,
            message: "theorem declaration missing type annotation ':'".to_string(),
        });
    }
    if !line.contains(":= by") {
        errors.push(SyntaxError {
            line: line_num,
            message: "theorem declaration missing ':= by' tactic block".to_string(),
        });
    }
}

fn check_axiom_declaration(line: &str, line_num: usize, errors: &mut Vec<SyntaxError>) {
    let after_axiom = &line["axiom ".len()..];
    let ident = after_axiom.split_whitespace().next().unwrap_or("");
    if !is_valid_lean_ident(ident) {
        errors.push(SyntaxError {
            line: line_num,
            message: format!("invalid identifier in axiom declaration: '{ident}'"),
        });
    }
    if !line.contains(':') {
        errors.push(SyntaxError {
            line: line_num,
            message: "axiom declaration missing type annotation ':'".to_string(),
        });
    }
}

fn check_abbrev_declaration(line: &str, line_num: usize, errors: &mut Vec<SyntaxError>) {
    let after_abbrev = &line["abbrev ".len()..];
    let ident = after_abbrev.split_whitespace().next().unwrap_or("");
    if !is_valid_lean_ident(ident) {
        errors.push(SyntaxError {
            line: line_num,
            message: format!("invalid identifier in abbrev declaration: '{ident}'"),
        });
    }
    if !line.contains(":=") {
        errors.push(SyntaxError {
            line: line_num,
            message: "abbrev declaration missing ':='".to_string(),
        });
    }
}

// ---------------------------------------------------------------------------
// Clause reference consistency
// ---------------------------------------------------------------------------

fn check_clause_references(source: &str, errors: &mut Vec<SyntaxError>) {
    let mut defined_clauses: HashSet<String> = HashSet::new();
    let mut referenced_clauses: Vec<(String, usize)> = Vec::new();

    for (line_idx, line) in source.lines().enumerate() {
        let line_num = line_idx + 1;
        let trimmed = line.trim();

        // Collect clause definitions: `def clause_N : Clause := ...`
        if trimmed.starts_with("def clause_") {
            if let Some(ident) = trimmed
                .strip_prefix("def ")
                .and_then(|s| s.split_whitespace().next())
            {
                defined_clauses.insert(ident.to_string());
            }
        }

        // Resolution step theorems implicitly define their result clause.
        // Format: `theorem resolution_step_N : resolves clause_A clause_B P clause_C := by`
        // The last clause_N before `:= by` is the resolvent (newly defined).
        if trimmed.starts_with("theorem resolution_step_") {
            let clause_refs: Vec<&str> = trimmed
                .split_whitespace()
                .filter(|w| w.starts_with("clause_"))
                .collect();
            // In `resolves clause_A clause_B P clause_C`, the last one is the result.
            if let Some(result_clause) = clause_refs.last() {
                defined_clauses.insert(result_clause.to_string());
            }
            // The parent clauses (all except the last) are references.
            for clause_ref in clause_refs.iter().take(clause_refs.len().saturating_sub(1)) {
                referenced_clauses.push((clause_ref.to_string(), line_num));
            }
        }

        // proof_valid references a clause that must already be defined.
        if trimmed.starts_with("theorem proof_valid") {
            for word in trimmed.split_whitespace() {
                if word.starts_with("clause_") {
                    referenced_clauses.push((word.to_string(), line_num));
                }
            }
        }
    }

    for (clause_ref, line_num) in &referenced_clauses {
        if !defined_clauses.contains(clause_ref.as_str()) {
            errors.push(SyntaxError {
                line: *line_num,
                message: format!("dangling clause reference: '{clause_ref}' is not defined"),
            });
        }
    }
}

// ---------------------------------------------------------------------------
// proof_valid presence
// ---------------------------------------------------------------------------

fn check_proof_valid_present(source: &str, errors: &mut Vec<SyntaxError>) {
    let has_proof_valid = source
        .lines()
        .any(|line| line.trim().starts_with("theorem proof_valid"));

    if !has_proof_valid {
        errors.push(SyntaxError {
            line: source.lines().count(),
            message: "missing 'theorem proof_valid' declaration".to_string(),
        });
    }
}

// ---------------------------------------------------------------------------
// by/decide pairing
// ---------------------------------------------------------------------------

fn check_by_decide_pairs(source: &str, errors: &mut Vec<SyntaxError>) {
    let lines: Vec<&str> = source.lines().collect();
    for (i, line) in lines.iter().enumerate() {
        let trimmed = line.trim();
        if trimmed.ends_with(":= by") {
            let next_content = lines
                .iter()
                .skip(i + 1)
                .find(|l| !l.trim().is_empty())
                .map(|l| l.trim());
            match next_content {
                Some("decide") => {}
                Some(other) => {
                    errors.push(SyntaxError {
                        line: i + 2,
                        message: format!("expected 'decide' after ':= by', found: '{other}'"),
                    });
                }
                None => {
                    errors.push(SyntaxError {
                        line: i + 1,
                        message: "':= by' at end of file with no tactic".to_string(),
                    });
                }
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_valid_lean_ident_accepts_simple_names() {
        assert!(is_valid_lean_ident("clause_1"));
        assert!(is_valid_lean_ident("x"));
        assert!(is_valid_lean_ident("_foo"));
        assert!(is_valid_lean_ident("a'"));
        assert!(is_valid_lean_ident("resolution_step_42"));
        assert!(is_valid_lean_ident("Clause.isEmpty")); // qualified name
        assert!(is_valid_lean_ident("a.b.c")); // multi-part qualified name
    }

    #[test]
    fn test_valid_lean_ident_rejects_invalid_names() {
        assert!(!is_valid_lean_ident(""));
        assert!(!is_valid_lean_ident("123"));
        assert!(!is_valid_lean_ident("1abc"));
        assert!(!is_valid_lean_ident("foo bar"));
        assert!(!is_valid_lean_ident("a+b"));
        assert!(!is_valid_lean_ident(".a")); // leading dot
        assert!(!is_valid_lean_ident("a.")); // trailing dot
    }

    #[test]
    fn test_balanced_delimiters_pass() {
        let src = "def x := (1 + [2])\n";
        let mut errors = Vec::new();
        check_balanced_delimiters(src, &mut errors);
        assert!(errors.is_empty());
    }

    #[test]
    fn test_unbalanced_paren_detected() {
        let src = "def x := (1 + 2\n";
        let mut errors = Vec::new();
        check_balanced_delimiters(src, &mut errors);
        assert_eq!(errors.len(), 1);
        assert!(errors[0].message.contains("unclosed"));
    }

    #[test]
    fn test_mismatched_delimiters_detected() {
        let src = "def x := (1 + 2]\n";
        let mut errors = Vec::new();
        check_balanced_delimiters(src, &mut errors);
        assert_eq!(errors.len(), 1);
        assert!(errors[0].message.contains("mismatched"));
    }
}
